#!/usr/bin/env python3
"""Reproduce DSLtk.hpp's embedded magic_enum v0.9.8 from an upstream checkout."""

import argparse
import hashlib
from pathlib import Path
import re


VERSION = "0.9.8"
SOURCE_SHA256 = "8e39051ab6167a80897f9b67c24da77f29f108209b11f5ec47ab8d74964611d6"
BEGIN = "// BEGIN DSLTK EMBEDDED MAGIC_ENUM\n"
END = "// END DSLTK EMBEDDED MAGIC_ENUM"
HEADERS = (
    "magic_enum.hpp",
    "magic_enum_all.hpp",
    "magic_enum_containers.hpp",
    "magic_enum_flags.hpp",
    "magic_enum_format.hpp",
    "magic_enum_fuse.hpp",
    "magic_enum_iostream.hpp",
    "magic_enum_switch.hpp",
    "magic_enum_utility.hpp",
)
LOCAL_INCLUDE = re.compile(r'^#include "(magic_enum[^"/]*\.hpp)"$', re.MULTILINE)


def amalgamate(source):
    headers = {name: (source / name).read_bytes() for name in HEADERS}
    digest = hashlib.sha256()
    for name in sorted(headers):
        digest.update(name.encode() + b"\0" + headers[name])
    if digest.hexdigest() != SOURCE_SHA256:
        raise SystemExit(f"Expected unmodified magic_enum v{VERSION} public headers")

    seen = set()

    def expand(name):
        if name in seen:
            return "// " + name + " is already embedded above."
        seen.add(name)
        text = headers[name].decode()
        text = LOCAL_INCLUDE.sub(lambda match: expand(match[1]), text)
        if name == "magic_enum_containers.hpp":
            # Minimal custom string aliases may support core reflection but
            # omit container-only operations. Defer those checks until use.
            text = text.replace(
                "class bitset {\n",
                "class bitset {\n"
                "  // DSLtk: keep optional string facilities dependent on E.\n"
                "  using string = std::conditional_t<std::is_enum_v<E>, magic_enum::string, void>;\n"
                "  using string_view = std::conditional_t<std::is_enum_v<E>, magic_enum::string_view, void>;\n",
                1,
            )
            text = text.replace("string_view::size_type", "std::size_t")
        if name == "magic_enum_format.hpp":
            # Discover std::format even when DSLtk.hpp is the first include.
            probe = (
                "// DSLtk: formatting is optional on C++20 standard libraries.\n"
                "#ifndef MAGIC_ENUM_USE_STD_MODULE\n"
                "#if __has_include(<format>)\n"
                "#include <format>\n"
                "#endif\n"
                "#endif\n\n"
            )
            text = text.replace("#if defined(__cpp_lib_format)",
                                probe + "#if defined(__cpp_lib_format)", 1)
        return f"// Embedded upstream header: {name}\n" + text.rstrip()

    result = expand("magic_enum_all.hpp")
    if seen != set(HEADERS) or LOCAL_INCLUDE.search(result):
        raise SystemExit("Incomplete amalgamation")
    return (
        BEGIN
        + "// Generated by scripts/update-magic-enum.py; do not edit this block.\n"
        + f"// Source: https://github.com/Neargye/magic_enum/tree/v{VERSION}\n"
        + f"// Public-header SHA256: {SOURCE_SHA256}\n"
        + "// Upstream include guards and MIT notices are retained.\n"
        + result + "\n" + END
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path, help="magic_enum v0.9.8 checkout root")
    parser.add_argument("--check", action="store_true", help="check without writing")
    args = parser.parse_args()
    header = Path(__file__).resolve().parents[1] / "DSLtk.hpp"
    text = header.read_text()
    before, block = text.split(BEGIN, 1)
    _, after = block.split(END, 1)
    updated = before + amalgamate(args.source / "include" / "magic_enum") + after
    if args.check:
        if updated != text:
            raise SystemExit("Embedded magic_enum is out of date")
    else:
        header.write_text(updated)


if __name__ == "__main__":
    main()
